Index: client/src/App.css
===================================================================
--- client/src/App.css	
+++ client/src/App.css	
@@ -1,684 +1,839 @@
 :root {
   --bg-primary: #0f172a;
   --bg-secondary: #1e293b;
   --bg-tertiary: #334155;
   --text-primary: #f8fafc;
   --text-secondary: #94a3b8;
   --text-muted: #64748b;
   --border: #334155;
   --accent: #3b82f6;
   --accent-hover: #2563eb;
   --success: #10b981;
   --warning: #f59e0b;
   --danger: #ef4444;
   --sidebar-width: 300px;
 }

 * {
   margin: 0;
   padding: 0;
   box-sizing: border-box;
 }

 body {
   font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
   background: var(--bg-primary);
   color: var(--text-primary);
   overflow: hidden;
 }

 .app {
   display: flex;
   height: 100vh;
 }

 /* Sidebar */
 .sidebar {
   width: var(--sidebar-width);
   background: var(--bg-secondary);
   border-right: 1px solid var(--border);
   display: flex;
   flex-direction: column;
 }

 .sidebar-content {
   flex: 1;
   overflow-y: auto;
   padding: 16px;
 }

 .sidebar-section {
   display: flex;
   gap: 4px;
   margin-bottom: 16px;
 }

 .tab-btn {
   flex: 1;
   display: flex;
   align-items: center;
   justify-content: center;
   gap: 6px;
   padding: 8px;
   background: transparent;
   border: 1px solid var(--border);
   border-radius: 6px;
   color: var(--text-secondary);
   cursor: pointer;
   font-size: 13px;
   transition: all 0.2s;
 }

 .tab-btn:hover {
   background: var(--bg-tertiary);
   color: var(--text-primary);
 }

 .tab-btn.active {
   background: var(--accent);
   border-color: var(--accent);
   color: white;
 }

 /* Flow List */
 .flow-list {
   display: flex;
   flex-direction: column;
   gap: 8px;
 }

 .flow-items {
   display: flex;
   flex-direction: column;
   gap: 4px;
 }

 .flow-item {
   display: flex;
   align-items: center;
   justify-content: space-between;
   padding: 10px 12px;
   background: var(--bg-tertiary);
   border-radius: 6px;
   cursor: pointer;
   transition: all 0.2s;
 }

 .flow-item:hover {
   background: #3d4f66;
 }

 .flow-item.active {
   background: var(--accent);
 }

 .flow-info {
   display: flex;
   flex-direction: column;
   gap: 2px;
 }

 .flow-name {
   font-size: 14px;
   font-weight: 500;
 }

 .flow-date {
   font-size: 11px;
   color: var(--text-muted);
 }

 .flow-item.active .flow-date {
   color: rgba(255,255,255,0.7);
 }

 .flow-actions {
   display: flex;
   gap: 4px;
   opacity: 0;
   transition: opacity 0.2s;
 }

 .flow-item:hover .flow-actions {
   opacity: 1;
 }

 /* Buttons */
 .btn {
   display: inline-flex;
   align-items: center;
   justify-content: center;
   gap: 6px;
   padding: 8px 16px;
   border: none;
   border-radius: 6px;
   font-size: 14px;
   cursor: pointer;
   transition: all 0.2s;
 }

 .btn-primary {
   background: var(--accent);
   color: white;
 }

 .btn-primary:hover {
   background: var(--accent-hover);
 }

 .btn-secondary {
   background: var(--bg-tertiary);
   color: var(--text-primary);
   border: 1px solid var(--border);
 }

 .btn-secondary:hover {
   background: #3d4f66;
 }

 .btn-block {
   width: 100%;
 }

 .btn-large {
   padding: 12px 24px;
   font-size: 16px;
 }

 .btn-icon {
   display: flex;
   align-items: center;
   justify-content: center;
   padding: 4px;
   background: transparent;
   border: none;
   color: var(--text-secondary);
   cursor: pointer;
   border-radius: 4px;
 }

 .btn-icon:hover {
   background: var(--bg-tertiary);
   color: var(--text-primary);
 }

 .btn-icon.danger:hover {
   background: var(--danger);
   color: white;
 }

 .btn-link {
   background: none;
   border: none;
   color: var(--accent);
   cursor: pointer;
   font-size: 13px;
 }

+.btn-sm {
+  padding: 6px 10px;
+  font-size: 12px;
+}
+
+.flow-actions-bar {
+  display: flex;
+  gap: 8px;
+  margin-top: 8px;
+}
+
 /* Editor Sidebar */
 .editor-sidebar {
   display: flex;
   flex-direction: column;
   gap: 16px;
 }

 .editor-sidebar h3 {
   font-size: 16px;
   font-weight: 600;
 }

 .flow-actions {
   display: flex;
   flex-direction: column;
   gap: 8px;
 }

 .node-palette {
   display: flex;
   flex-direction: column;
   gap: 12px;
 }

 .node-palette h4 {
   font-size: 12px;
   text-transform: uppercase;
   color: var(--text-muted);
   letter-spacing: 0.5px;
 }

 .palette-item {
   display: flex;
   align-items: center;
   gap: 8px;
   padding: 8px 12px;
   background: var(--bg-tertiary);
   border-radius: 6px;
   cursor: grab;
   font-size: 13px;
   transition: all 0.2s;
 }

 .palette-item:hover {
   background: #3d4f66;
 }

 .palette-item:active {
   cursor: grabbing;
 }

 .dot {
   width: 8px;
   height: 8px;
   border-radius: 50%;
 }

 /* Main Content */
 .main-content {
   flex: 1;
   position: relative;
 }

 .empty-state {
   display: flex;
   flex-direction: column;
   align-items: center;
   justify-content: center;
   height: 100%;
   gap: 16px;
 }

 .empty-state h1 {
   font-size: 32px;
   background: linear-gradient(135deg, var(--accent), var(--success));
   -webkit-background-clip: text;
   -webkit-text-fill-color: transparent;
 }

 .empty-state p {
   color: var(--text-secondary);
   font-size: 16px;
 }

 .flow-editor {
   width: 100%;
   height: 100%;
 }

 /* Custom Node */
 .custom-node {
   background: var(--bg-secondary);
   border: 1px solid var(--border);
   border-radius: 8px;
   min-width: 180px;
   box-shadow: 0 2px 8px rgba(0,0,0,0.3);
 }

 .custom-node.trigger {
   border-left: 3px solid var(--success);
 }

 .custom-node.action {
   border-left: 3px solid var(--accent);
 }

 .custom-node.logic {
   border-left: 3px solid var(--warning);
 }

 .node-header {
   display: flex;
   align-items: center;
   gap: 8px;
   padding: 10px 12px;
   cursor: pointer;
 }

 .node-icon {
   display: flex;
   align-items: center;
   justify-content: center;
   width: 24px;
   height: 24px;
   border-radius: 4px;
   color: white;
 }

 .node-label {
   font-size: 13px;
   font-weight: 500;
 }

 .node-config {
   padding: 8px 12px 12px;
   border-top: 1px solid var(--border);
   display: flex;
   flex-direction: column;
   gap: 8px;
 }

 .config-field {
   display: flex;
   flex-direction: column;
   gap: 4px;
 }

 .config-field label {
   font-size: 11px;
   color: var(--text-muted);
   text-transform: uppercase;
 }

 .config-field input,
 .config-field select {
   padding: 6px 8px;
   background: var(--bg-tertiary);
   border: 1px solid var(--border);
   border-radius: 4px;
   color: var(--text-primary);
   font-size: 12px;
 }

 .config-field input:focus,
 .config-field select:focus {
   outline: none;
   border-color: var(--accent);
 }

 /* React Flow overrides */
 .react-flow__node {
   padding: 0;
 }

 .react-flow__handle {
   width: 10px;
   height: 10px;
   background: var(--accent);
   border: 2px solid var(--bg-secondary);
 }

 .react-flow__handle-left {
   left: -5px;
 }

 .react-flow__handle-right {
   right: -5px;
 }

 .react-flow__controls {
   background: var(--bg-secondary);
   border: 1px solid var(--border);
   border-radius: 8px;
   box-shadow: 0 2px 8px rgba(0,0,0,0.3);
 }

 .react-flow__controls button {
   background: var(--bg-secondary);
   border-bottom: 1px solid var(--border);
   color: var(--text-primary);
 }

 .react-flow__controls button:hover {
   background: var(--bg-tertiary);
 }

 .react-flow__background {
   background: var(--bg-primary);
 }

 /* Execution Panel */
 .execution-panel {
   display: flex;
   flex-direction: column;
   gap: 12px;
 }

 .execution-panel h3 {
   font-size: 16px;
 }

 .execution-list {
   display: flex;
   flex-direction: column;
   gap: 4px;
 }

 .execution-item {
   display: flex;
   align-items: center;
   gap: 8px;
   padding: 8px 12px;
   background: var(--bg-tertiary);
   border-radius: 6px;
   cursor: pointer;
   transition: all 0.2s;
 }

 .execution-item:hover {
   background: #3d4f66;
 }

 .execution-item.active {
   background: var(--accent);
 }

 .execution-info {
   flex: 1;
   display: flex;
   flex-direction: column;
   gap: 2px;
 }

 .execution-flow {
   font-size: 13px;
   font-weight: 500;
 }

 .execution-time {
   font-size: 11px;
   color: var(--text-muted);
 }

 .execution-detail {
   margin-top: 12px;
   padding: 12px;
   background: var(--bg-tertiary);
   border-radius: 6px;
   display: flex;
   flex-direction: column;
   gap: 8px;
 }

 .execution-detail h4 {
   font-size: 14px;
 }

 .execution-detail p {
   font-size: 13px;
   color: var(--text-secondary);
 }

 .node-results {
   margin-top: 8px;
   display: flex;
   flex-direction: column;
   gap: 4px;
 }

 .node-result {
   display: flex;
-  align-items: center;
-  gap: 8px;
+  flex-direction: column;
+  gap: 4px;
   padding: 6px 8px;
   background: var(--bg-secondary);
   border-radius: 4px;
   font-size: 12px;
 }

 .node-result.error {
   border-left: 2px solid var(--danger);
 }

+.node-result-header {
+  display: flex;
+  align-items: center;
+  gap: 4px;
+  cursor: pointer;
+}
+
+.node-result-toggle {
+  background: transparent;
+  border: none;
+  color: var(--text-muted);
+  cursor: pointer;
+  padding: 2px;
+  display: flex;
+  align-items: center;
+}
+
+.node-result-type {
+  flex: 1;
+  font-weight: 500;
+}
+
+.node-result-details {
+  padding: 8px;
+  background: var(--bg-primary);
+  border-radius: 4px;
+  margin-top: 4px;
+}
+
+.node-output {
+  display: flex;
+  flex-direction: column;
+  gap: 8px;
+}
+
+.output-section {
+  display: flex;
+  flex-direction: column;
+  gap: 4px;
+}
+
+.output-section.output-error {
+  border-left: 2px solid var(--danger);
+  padding-left: 8px;
+}
+
+.output-label {
+  font-size: 10px;
+  text-transform: uppercase;
+  color: var(--text-muted);
+  font-weight: 600;
+}
+
+.output-content {
+  background: var(--bg-secondary);
+  padding: 8px;
+  border-radius: 4px;
+  font-size: 11px;
+  font-family: 'JetBrains Mono', 'Fira Code', monospace;
+  overflow-x: auto;
+  white-space: pre-wrap;
+  word-break: break-all;
+  max-height: 200px;
+  overflow-y: auto;
+  margin: 0;
+}
+
+.output-exit {
+  font-size: 11px;
+  color: var(--text-muted);
+}
+
+.output-json {
+  background: var(--bg-secondary);
+  padding: 8px;
+  border-radius: 4px;
+  font-size: 11px;
+  font-family: 'JetBrains Mono', 'Fira Code', monospace;
+  overflow-x: auto;
+  white-space: pre-wrap;
+  margin: 0;
+  max-height: 200px;
+  overflow-y: auto;
+}
+
+.output-empty {
+  color: var(--text-muted);
+  font-size: 11px;
+  font-style: italic;
+}
+
 /* Status Badges */
 .status-badge {
   padding: 2px 8px;
   border-radius: 12px;
   font-size: 11px;
   text-transform: uppercase;
   font-weight: 500;
 }

 .status-badge.active,
 .status-badge.completed {
   background: rgba(16, 185, 129, 0.2);
   color: var(--success);
 }

 .status-badge.inactive {
   background: rgba(100, 116, 139, 0.2);
   color: var(--text-muted);
 }

 .status-badge.running {
   background: rgba(59, 130, 246, 0.2);
   color: var(--accent);
 }

 .status-badge.failed,
 .status-badge.error {
   background: rgba(239, 68, 68, 0.2);
   color: var(--danger);
 }

 /* Modal */
 .modal-overlay {
   position: fixed;
   inset: 0;
   background: rgba(0,0,0,0.7);
   display: flex;
   align-items: center;
   justify-content: center;
   z-index: 1000;
 }

 .modal {
   background: var(--bg-secondary);
   border: 1px solid var(--border);
   border-radius: 12px;
   padding: 24px;
   width: 100%;
   max-width: 500px;
   max-height: 90vh;
   overflow-y: auto;
 }

 .modal-header {
   display: flex;
   align-items: center;
   justify-content: space-between;
   margin-bottom: 20px;
 }

 .modal-header h2 {
   display: flex;
   align-items: center;
   gap: 8px;
   font-size: 18px;
 }

 .form-group {
   margin-bottom: 16px;
 }

 .form-group label {
   display: block;
   font-size: 13px;
   font-weight: 500;
   margin-bottom: 6px;
   color: var(--text-secondary);
 }

 .form-group small {
   display: block;
   margin-top: 4px;
   font-size: 11px;
   color: var(--text-muted);
 }

 .input {
   width: 100%;
   padding: 8px 12px;
   background: var(--bg-tertiary);
   border: 1px solid var(--border);
   border-radius: 6px;
   color: var(--text-primary);
   font-size: 14px;
 }

 .input:focus {
   outline: none;
   border-color: var(--accent);
 }

 .preset-grid {
   display: grid;
   grid-template-columns: repeat(2, 1fr);
   gap: 8px;
   margin-bottom: 12px;
 }

 .preset-btn {
   padding: 8px 12px;
   background: var(--bg-tertiary);
   border: 1px solid var(--border);
   border-radius: 6px;
   color: var(--text-primary);
   cursor: pointer;
   font-size: 12px;
   transition: all 0.2s;
 }

 .preset-btn:hover {
   background: #3d4f66;
 }

 .preset-btn.active {
   background: var(--accent);
   border-color: var(--accent);
 }

 .modal-actions {
   display: flex;
   justify-content: flex-end;
   gap: 8px;
   margin-top: 20px;
 }

 /* Utilities */
 .text-green { color: var(--success); }
 .text-red { color: var(--danger); }
 .spin { animation: spin 1s linear infinite; }
 .empty { color: var(--text-muted); font-size: 14px; text-align: center; padding: 20px; }
 .error { color: var(--danger); }

+/* Error Banner */
+.error-banner {
+  position: fixed;
+  top: 0;
+  left: 0;
+  right: 0;
+  z-index: 9999;
+  background: var(--danger);
+  color: white;
+  padding: 10px 16px;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  font-size: 14px;
+  box-shadow: 0 2px 8px rgba(0,0,0,0.3);
+}
+
+.error-banner-text {
+  flex: 1;
+}
+
+.error-banner-close {
+  background: transparent;
+  border: none;
+  color: white;
+  cursor: pointer;
+  padding: 4px;
+  border-radius: 4px;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+}
+
+.error-banner-close:hover {
+  background: rgba(255,255,255,0.2);
+}
+
+/* Loading Overlay */
+.loading-overlay {
+  position: fixed;
+  inset: 0;
+  z-index: 9998;
+  background: rgba(15, 23, 42, 0.5);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  pointer-events: none;
+}
+
+.loading-overlay svg {
+  color: var(--accent);
+}
+
 @keyframes spin {
   from { transform: rotate(0deg); }
   to { transform: rotate(360deg); }
 }

 /* Scrollbar */
 ::-webkit-scrollbar {
   width: 8px;
 }

 ::-webkit-scrollbar-track {
   background: var(--bg-primary);
 }

 ::-webkit-scrollbar-thumb {
   background: var(--bg-tertiary);
   border-radius: 4px;
 }

 ::-webkit-scrollbar-thumb:hover {
   background: #4a5568;
 }

