     if (triggerNodes.length === 0 && flow.nodes.length > 0) {
       // Execute from first node if no trigger
       await executeNode(flow, flow.nodes[0], execution, wsManager);
     } else {
       // Execute from each trigger
       for (const triggerNode of triggerNodes) {
         await executeFromNode(flow, triggerNode, execution, wsManager);
       }
     }

     execution.status = 'completed';
     execution.completedAt = new Date().toISOString();
     flowStore.saveExecution(execution);
     emit(wsManager, flow.id, { type: 'execution:complete', execution });
   } catch (error) {
     execution.status = 'failed';
     execution.error = error.message;
     execution.completedAt = new Date().toISOString();
     flowStore.saveExecution(execution);
     emit(wsManager, flow.id, { type: 'execution:error', execution });
   }

