     } else if (nodeType === 'action_type_text') {
       output = await automation.typeText(node.data);
     } else if (nodeType === 'action_screenshot') {
       output = await automation.screenshot(node.data);
     } else if (nodeType === 'action_command') {
       output = await automation.runCommand(node.data, execution.context);
     } else if (nodeType === 'action_delay') {
       await Bun.sleep(node.data.duration || 1000);
       output = { delayed: true };
     } else if (nodeType === 'action_notify') {
       output = await automation.notify(node.data);
     } else if (nodeType === 'logic_condition') {
       const result = evalCondition(node.data.condition, execution.context);
       output = { result };
     } else if (nodeType === 'logic_loop') {
       output = await executeLoop(flow, node, execution, wsManager);
     } else if (nodeType === 'logic_variable') {
       execution.context.variables[node.data.name] = node.data.value;
       output = { name: node.data.name, value: node.data.value };
     } else if (nodeType === 'action_http') {
-      output = await automation.httpRequest(node.data);
+      output = await automation.httpRequest(node.data, execution.context);
+    } else if (nodeType === 'action_email') {
+      output = await automation.sendEmail(node.data, execution.context);
     } else {
       output = { executed: true };
     }

     nodeResult.status = 'completed';
     nodeResult.output = output;
     nodeResult.completedAt = new Date().toISOString();
     emit(wsManager, execution.flowId, { type: 'node:complete', nodeId: node.id, output });

     // Find connected nodes and execute them
     const connectedEdges = flow.edges.filter(e => e.source === node.id);

     for (const edge of connectedEdges) {
       const targetNode = flow.nodes.find(n => n.id === edge.target);
       if (!targetNode) continue;

       // For condition nodes, check which path to take
       if (nodeType === 'logic_condition') {
         const handle = edge.sourceHandle || 'true';
         if ((handle === 'true' && output.result) || (handle === 'false' && !output.result)) {
           await executeNode(flow, targetNode, execution, wsManager);
         }
       } else {
         await executeNode(flow, targetNode, execution, wsManager);
       }
     }
   } catch (error) {
     nodeResult.status = 'error';
     nodeResult.error = error.message;
     nodeResult.completedAt = new Date().toISOString();
     emit(wsManager, execution.flowId, { type: 'node:error', nodeId: node.id, error: error.message });
     throw error;
   }
 }

 async function executeLoop(flow, loopNode, execution, wsManager) {
   const count = loopNode.data.count || 1;
   const delay = loopNode.data.delay || 0;

   for (let i = 0; i < count; i++) {
     execution.context.loopIndex = i;

     const loopEdges = flow.edges.filter(e => e.source === loopNode.id);
     for (const edge of loopEdges) {
       const targetNode = flow.nodes.find(n => n.id === edge.target);
       if (targetNode) {
         await executeNode(flow, targetNode, execution, wsManager);
       }
     }

     if (delay > 0 && i < count - 1) {
       await Bun.sleep(delay);
     }
   }

   return { iterations: count };
 }

 function evalCondition(condition, context) {
   try {
     const fn = new Function('context', `return ${condition}`);
     return !!fn(context);
   } catch {
     return false;
   }
 }

 function emit(wsManager, flowId, data) {
   if (!wsManager) return;
   wsManager.publish(flowId, JSON.stringify(data));
 }

