 import cron from 'node-cron';
 import { executeFlow } from '../engine/executor.js';
 import { flowStore } from '../services/store.js';
+import { wsManager } from './websocket.js';

 class Scheduler {
   constructor() {
     this.jobs = new Map();
   }

   add(flowId, cronExpression, options = {}) {
     // Remove existing schedule for this flow
     this.remove(flowId);

     const job = cron.schedule(cronExpression, async () => {
       const flow = flowStore.get(flowId);
       if (flow && flow.enabled) {
-        await executeFlow(flow, { triggerType: 'schedule' });
+        await executeFlow(flow, { triggerType: 'schedule' }, wsManager);
       }
     }, {
       timezone: options.timezone || 'America/New_York'
     });

     this.jobs.set(flowId, { job, cronExpression, options });
     job.start();

     return { flowId, cronExpression, status: 'active' };
   }

   remove(flowId) {
     const existing = this.jobs.get(flowId);
     if (existing) {
       existing.job.stop();
       this.jobs.delete(flowId);
     }
   }

   getByFlowId(flowId) {
     const job = this.jobs.get(flowId);
     if (!job) return [];
     return [{ flowId, cronExpression: job.cronExpression, status: 'active' }];
   }

   getAll() {
     return Array.from(this.jobs.entries()).map(([flowId, job]) => ({
       flowId,
       cronExpression: job.cronExpression,
       status: 'active'
     }));
   }
 }

 export const scheduler = new Scheduler();

