+import { executeFlow } from '../engine/executor.js';
+import { flowStore } from '../services/store.js';
+import { wsManager } from './websocket.js';
+
+class WebhookRegistry {
+  constructor() {
+    this.webhooks = new Map();
+  }
+
+  register(flowId, path) {
+    this.webhooks.set(path, { flowId, path });
+  }
+
+  unregister(flowId) {
+    const flow = flowStore.get(flowId);
+    if (!flow) return;
+    
+    const webhookNodes = flow.nodes.filter(n => n.data?.nodeType === 'trigger_webhook');
+    for (const node of webhookNodes) {
+      const path = node.data.path;
+      if (path && this.webhooks.has(path)) {
+        this.webhooks.delete(path);
+      }
+    }
+  }
+
+  syncFlow(flowId) {
+    this.unregister(flowId);
+    
+    const flow = flowStore.get(flowId);
+    if (!flow) return;
+    
+    const webhookNodes = flow.nodes.filter(n => n.data?.nodeType === 'trigger_webhook');
+    for (const node of webhookNodes) {
+      const path = node.data.path;
+      if (path) {
+        this.register(flowId, path);
+      }
+    }
+  }
+
+  getWebhook(path) {
+    return this.webhooks.get(path);
+  }
+
+  getAll() {
+    return Array.from(this.webhooks.values());
+  }
+
+  async handleWebhook(path, body, query) {
+    const webhook = this.webhooks.get(path);
+    if (!webhook) return null;
+
+    const flow = flowStore.get(webhook.flowId);
+    if (!flow || !flow.enabled) {
+      return { error: 'Flow not found or disabled', status: 404 };
+    }
+
+    const triggerData = {
+      triggerType: 'webhook',
+      webhookPath: path,
+      body,
+      query: Object.fromEntries(query.entries()),
+      timestamp: new Date().toISOString()
+    };
+
+    const executionId = await executeFlow(flow, triggerData, wsManager);
+    return { executionId, status: 'triggered' };
+  }
+}
+
+export const webhookRegistry = new WebhookRegistry();

